frappe.ui.form.on('Leave Application', {
    onload: function(frm) {
        if (frm.doc.leave_type) {
            // Fetch blocked dates for the selected leave type
            get_blocked_dates(frm);
        }
    },
    leave_type: function(frm) {
        // Re-fetch blocked dates when leave type is changed
        if (frm.doc.leave_type) {
            get_blocked_dates(frm);
        }
    },
    from_date: function(frm) {
        // Validate the entered 'from_date'
        validate_single_date(frm, frm.doc.from_date, 'from_date');
    },
    to_date: function(frm) {
        // Validate the entered 'to_date'
        validate_single_date(frm, frm.doc.to_date, 'to_date');
    },
    validate: function(frm) {
        // Ensure that the selected dates are not in the blocked list before saving the form
        if (frm.doc.from_date && frm.doc.to_date) {
            handle_blocked_dates(frm); // Call before validation
            validate_dates(frm); // Ensure validation after handling blocked dates
        }
    }
});

function get_blocked_dates(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Leave Block List",
            filters: {
                leave_type: frm.doc.leave_type
            },
            fields: ["name"],
            order_by: "creation desc",
            limit: 1
        },
        callback: function(response) {
            if (response.message.length > 0) {
                var leave_block_list_name = response.message[0].name;

                // Fetch the blocked dates and reasons from the child table
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Leave Block List",
                        name: leave_block_list_name
                    },
                    callback: function(response) {
                        if (response.message) {
                            // Create an array of objects with block_date and reason
                            var blocked_dates_with_reasons = response.message.leave_block_list_dates.map(entry => ({
                                block_date: entry.block_date,
                                reason: entry.reason
                            }));
                            frm.blocked_dates_with_reasons = blocked_dates_with_reasons;
                        }
                    }
                });
            } else {
                // No block list found for this leave type
                frm.blocked_dates_with_reasons = []; // Clear blocked dates array

                // Ensure fields are visible
                frm.toggle_display('leave_balance', true);
                frm.toggle_display('total_leave_days', true);
            }
        }
    });
}


// Function to validate if the manually entered date is blocked
function validate_single_date(frm, selected_date, fieldname) {
    if (selected_date) {
        var blocked_dates = frm.blocked_dates_with_reasons.map(entry => entry.block_date);

        // Check if the entered date is in the blocked dates list
        if (blocked_dates.includes(selected_date)) {
            // Find the blocked entry to display the reason
            var blocked_entry = frm.blocked_dates_with_reasons.find(entry => entry.block_date === selected_date);
            var formatted_date = frappe.datetime.global_date_format(selected_date); // Convert to user format

            frappe.msgprint({
                title: __('Blocked Leave Days'),
                indicator: 'red',
                message: __('{0} is blocked: {1}', [formatted_date, blocked_entry.reason])
            });

            // Clear the field so the user can enter a valid date
            frm.set_value(fieldname, '');

            // Handle blocked dates (clear and hide fields)
            handle_blocked_dates(frm);
        }
    }
}


function validate_dates(frm) {
    var blocked_dates = frm.blocked_dates_with_reasons.map(entry => entry.block_date);

    // Check if the selected from_date or to_date is in the blocked dates list
    if (blocked_dates.includes(frm.doc.from_date) || blocked_dates.includes(frm.doc.to_date)) {
        // First handle the blocked dates (clear fields, hide, etc.)
        handle_blocked_dates(frm);

        frappe.msgprint({
            title: __('Blocked Leave Days'),
            indicator: 'red',
            message: __('You cannot apply for leave on blocked dates.')
        });
    }
}

// Function to handle blocked dates and hide leave_balance and total_leave_days fields
function handle_blocked_dates(frm) {
    var blocked_dates = frm.blocked_dates_with_reasons.map(entry => entry.block_date);

    // Check if the selected from_date or to_date is in the blocked dates list
    if (blocked_dates.includes(frm.doc.from_date) || blocked_dates.includes(frm.doc.to_date)) {
        // Hide and clear the leave_balance and total_leave_days fields
        frm.set_value('leave_balance', '');
        frm.set_value('total_leave_days', '');
        frm.toggle_display('leave_balance', false);
        frm.toggle_display('total_leave_days', false);
    } else {
        // Show the fields if no blocked dates are selected
        frm.toggle_display('leave_balance', true);
        frm.toggle_display('total_leave_days', true);
    }
}

