frappe.ui.form.on('Vehicle Maintenance Allowance', {
    refresh(frm) {
        // fetch the latest internal audit timestamp and cache it
        // if the form is saved (has name)
        frm._vma_reference_date = null;

        if (frm.docname) {
            frappe.call({
                method: "nacoc.my_scripts.vehicle_maintenance_allowance_helpers.get_latest_internal_audit_timestamp",
                args: { docname: frm.docname },
                callback: function(r) {
                    if (r && r.message) {
                        frm._vma_reference_date = r.message; // yyyy-mm-dd or null
                    } else {
                        frm._vma_reference_date = null;
                    }
                    // update warnings after we have the reference date
                    update_date_warnings(frm);
                }
            });
        } else {
            // new doc - no need to wait, just update using today
            update_date_warnings(frm);
        }
    },

    validate(frm) {
        // ensure we use the cached reference date if available and form is not dirty,
        // otherwise use today's date
        const ref_date = (frm.is_dirty() || !frm._vma_reference_date) ? frappe.datetime.get_today() : frm._vma_reference_date;

        const invalids = get_invalid_date_fields(frm, ref_date);

        if (invalids.length > 0) {
            frappe.msgprint({
                title: "Invalid or Expired Dates",
                message: invalids.map(i => i.message).join("<br>"),
                indicator: "red"
            });
            frappe.validated = false;
        }
    }
});

/* ---------------------------------------------
   CORE FUNCTIONS
---------------------------------------------- */

function format_dd_mm_yyyy(date_str) {
    if (!date_str) return "";
    const [y, m, d] = date_str.split("-");
    return `${d}-${m}-${y}`;
}

// Get invalid/expired fields with messages relative to reference_date (yyyy-mm-dd)
function get_invalid_date_fields(frm, reference_date) {
    const invalids = [];

    function add_invalid(field, label, message) {
        invalids.push({ field, label, message });
    }

    const today = frappe.datetime.get_today();
    const ref = reference_date || today;

    // expiry fields --------------------------------
    const expiry_fields = [
        { field: "drivers_licence_expiry_date", label: "Driver’s Licence" },
        { field: "road_worthiness_expiry_date", label: "Road Worthiness" },
        { field: "vehicle_insurance_expiry_date", label: "Vehicle Insurance" }
    ];

    expiry_fields.forEach(item => {
        const value = frm.doc[item.field];
        if (!value) return;

        // compare using frappe date objects
        if (frappe.datetime.str_to_obj(value) < frappe.datetime.str_to_obj(ref)) {
            add_invalid(
                item.field,
                item.label,
                `${item.label} expired on ${format_dd_mm_yyyy(value)} relative to submission date of ${format_dd_mm_yyyy(ref)}.`
            );
        }
    });

    // Vehicle registration date cannot be after reference_date
    if (frm.doc.vehicle_registration_date &&
        frappe.datetime.str_to_obj(frm.doc.vehicle_registration_date) > frappe.datetime.str_to_obj(ref)) {

        add_invalid(
            "vehicle_registration_date",
            "Vehicle Registration Date",
            `Vehicle Registration Date (${format_dd_mm_yyyy(frm.doc.vehicle_registration_date)}) cannot be later than submission date of ${format_dd_mm_yyyy(ref)}.`
        );
    }

    return invalids;
}

// Update dashboard: highlight fields, add icons and dashboard block
function update_date_warnings(frm) {
    // clear previous indicators
    clear_dashboard_warnings(frm);
    clear_field_icons(frm);
    reset_field_styles(frm);

    // choose reference date:
    const ref_date = (frm.is_dirty() || !frm._vma_reference_date) ? frappe.datetime.get_today() : frm._vma_reference_date;

    const invalids = get_invalid_date_fields(frm, ref_date);
    if (invalids.length === 0) return;

    let dashboard_html = `
        <div style="
            padding: 10px;
            background: #fff3cd;
            border-left: 4px solid #856404;
            border-radius: 4px;
            margin-bottom: 10px;
        ">
            <strong>⚠️ Date Issues Found</strong><br>
            <ul style="margin-top: 8px;">
    `;

    invalids.forEach(i => {
        mark_field_red(frm, i.field);
        add_warning_icon(frm, i.field);

        // Message already uses dd-mm-yyyy
        const msg = frappe.utils.escape_html(i.message);
        dashboard_html += `<li>${msg}</li>`;
    });

    dashboard_html += "</ul></div>";

    // use a consistent section key so we can clear it before adding
    frm.dashboard.hide("VMA Date Warnings");
    frm.dashboard.add_section(dashboard_html, "VMA Date Warnings");
    frm.dashboard.show();
}


/* ---------------------------------------------
   UI HELPERS
---------------------------------------------- */

function mark_field_red(frm, fieldname) {
    const df = frm.fields_dict[fieldname];
    if (!df || !df.$wrapper) return;
    const input = df.$wrapper.find("input");
    input.css({
        "background-color": "#ffe6e6",
        "border": "1px solid #d9534f"
    });
}

function add_warning_icon(frm, fieldname) {
    const df = frm.fields_dict[fieldname];
    if (!df || !df.$wrapper) return;
    df.$wrapper.find(".date-warning-icon").remove();
    const icon_html = `
        <span class="date-warning-icon" 
              style="color:#d9534f; margin-left:5px;"
              title="This date is invalid or expired">
              ⚠️
        </span>
    `;
    df.$wrapper.find("input").after(icon_html);
}

function clear_field_icons(frm) {
    Object.values(frm.fields_dict).forEach(df => {
        if (df && df.$wrapper) {
            df.$wrapper.find(".date-warning-icon").remove();
        }
    });
}

function reset_field_styles(frm) {
    Object.values(frm.fields_dict).forEach(df => {
        if (df && df.$wrapper) {
            const input = df.$wrapper.find("input");
            input.css({
                "background-color": "",
                "border": ""
            });
        }
    });
}

function clear_dashboard_warnings(frm) {
    // safe clear: clear the named section key
    if (frm.dashboard && frm.dashboard.sections) {
        frm.dashboard.hide("VMA Date Warnings");
        frm.dashboard.show();
    }
}

frappe.ui.form.on("Weekly Regional Report", {
    refresh: function(frm) {
        if (!frm.doc.weekly_report || !frm.doc.last_generated_on || frm.doc.last_data_update > frm.doc.last_generated_on) {
            frm.add_custom_button("Create Report", () => {
                frappe.call({
                    method: "nacoc.my_scripts.weekly_regional_reports.generate_weekly_report",
                    args: { docname: frm.doc.name },
                    freeze: true,
                    freeze_message: __("Generating Report..."),
                    callback: function(r) {
                        if (r.message) {
                            frm.set_value("weekly_report", r.message);
                            frm.set_value("last_generated_on", frappe.datetime.now_datetime());
                            frm.save();
                            frappe.msgprint("Weekly report generated successfully");
                            frm.refresh();
                        }
                    }
                });
            }).addClass("btn-primary");
        }
    },
    week_start_date: function(frm) {
        if (frm.doc.week_start_date) {
            let start = frappe.datetime.str_to_obj(frm.doc.week_start_date);

            // Calculate ISO week number
            let date = new Date(start.getTime());
            date.setHours(0,0,0,0);

            date.setDate(date.getDate() + 3 - ((date.getDay() + 6) % 7));
            let week1 = new Date(date.getFullYear(), 0, 4);
            let weekNumber = 1 + Math.round(
                ((date.getTime() - week1.getTime()) / 86400000 - 3 + ((week1.getDay() + 6) % 7)) / 7
            );

            frm.set_value("week_number", weekNumber);

            let monthNames = [
                "January", "February", "March", "April", "May", "June",
                "July", "August", "September", "October", "November", "December"
            ];
            frm.set_value("month", monthNames[start.getMonth()]);

            frm.set_value("year", start.getFullYear());

            // Optional: auto-fill week_end_date as +6 days
            let end = frappe.datetime.add_days(frm.doc.week_start_date, 6);
            frm.set_value("week_end_date", end);
        }
    }
});

