frappe.ui.form.on('Book', {
    refresh: function(frm) {
        // Create and inject the CSS for the spinner overlay if it doesn't exist
        if ($('#isbn-spinner-styles').length === 0) {
            const css = `
                #isbn-spinner-overlay {
                    display: none;
                    position: fixed;
                    top: 0;
                    left: 0;
                    width: 100%;
                    height: 100%;
                    background-color: rgba(255, 255, 255, 0.8);
                    z-index: 1000;
                    text-align: center;
                    line-height: 100vh;
                }
                #isbn-spinner-overlay i {
                    font-size: 6rem;
                    color: #000;
                }
            `;
            $('<style>', {
                id: 'isbn-spinner-styles',
                type: 'text/css',
                text: css
            }).appendTo('head');
        }

        // Add the overlay HTML to the form if it doesn't exist
        if ($('#isbn-spinner-overlay').length === 0) {
            $('<div>', {
                id: 'isbn-spinner-overlay',
                html: '<i class="fa fa-spinner fa-pulse fa-fw"></i>'
            }).appendTo('body');
        }

        // Namespaced + unbound-before-bound so refresh (e.g. after save)
        // doesn't stack a duplicate handler that fires the lookup twice.
        frm.fields_dict.isbn.$input.off('blur.fetch_book_details').on('blur.fetch_book_details', function() {
            if (frm.doc.isbn) {
                // Show the overlay with spinner
                $('#isbn-spinner-overlay').show();

                fetchBookDetails(frm.doc.isbn).then(bookDetails => {
                    if (bookDetails) {
                        frm.set_value('book_title', bookDetails.book_title);
                        frm.set_value('book_type', bookDetails.book_type);
                        frm.set_value('category', bookDetails.category);
                        frm.set_value('year_published', bookDetails.year_published);
                        frm.set_value('number_of_pages', bookDetails.number_of_pages);
                        frm.set_value('book_cover', bookDetails.book_cover);
                        frm.set_value('book_description', bookDetails.book_description);
                    } else {
                        frappe.msgprint(__('No details found for ISBN {0}', [frm.doc.isbn]));
                    }
                }).catch(error => {
                    frappe.msgprint(__('Error fetching details: {0}', [error]));
                }).finally(() => {
                    // Hide the overlay with spinner
                    $('#isbn-spinner-overlay').hide();
                });
            }
        });
    }
});

async function fetchBookDetails(isbn) {
    const url = `https://www.googleapis.com/books/v1/volumes?q=isbn:${isbn}`;
    try {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Failed to fetch details for ISBN ${isbn}: ${response.status}`);
        }
        const data = await response.json();
        if (data.totalItems > 0) {
            const bookData = data.items[0].volumeInfo;
            const bookDesc = data.items[0].searchInfo;
            return {
                book_title: bookData.title || '',
                book_type: bookData.printType || '',
                isbn: isbn,
                year_published: moment(bookData.publishedDate).format('YYYY') || '',
                category: bookData.categories ? bookData.categories[0] : '',
                number_of_pages: bookData.pageCount || '',
                book_cover: bookData.imageLinks?.thumbnail || '',
                book_description: bookDesc?.textSnippet.replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/--$/, "") || ''
            };
        } else {
            console.error(`No details found for ISBN ${isbn}`);
            return null;
        }
    } catch (error) {
        console.error(`Error: ${error}`);
        throw error;
    }
}

