frappe.ui.form.on('Employee Checkin', {
    refresh: function(frm) {
        // Destroy any existing map bound to this container (Frappe's own
        // Geolocation control map on first render, or our own map from a
        // previous refresh) before creating a new one - otherwise Leaflet
        // throws "Map container is already initialized".
        if (frm.fields_dict.custom_location.map) {
            frm.fields_dict.custom_location.map.remove();
        }

        // Initialize the map with only zoom controls
        var map = L.map(frm.fields_dict.custom_location.wrapper).setView([0, 0], 10);

        // Adding tile layer (map background)
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 19
        }).addTo(map);

        // Remove drawing and editing tools
        map.zoomControl.setPosition('topright');

        // Locate the user
        map.locate({ setView: true, maxZoom: 13 });

        map.on('locationfound', function (e) {
            var radius = e.accuracy;

            L.marker(e.latlng).addTo(map)
                .bindPopup('Approximate Checkin').openPopup();

            L.circle(e.latlng, radius).addTo(map);

            frm.set_value("device_id", e.latitude + ', ' + e.longitude);
        });

        map.on('locationerror', function (e) {
            console.error('Geolocation error: ' + e.message);
        });

        // Update the map reference in the form
        frm.fields_dict.custom_location.map = map;
    }
});

