frappe.ui.form.on('Clearance Permit', {
    onload: function(frm) {
        if (frm.doc.quantity != null) {
            let formatted = Number(frm.doc.quantity).toLocaleString();
            frm.fields_dict.quantity.$wrapper.find('input').val(formatted);
        }
    },
    before_save: function(frm) {
        if (typeof frm.doc.quantity === 'string') {
            frm.set_value('quantity', parseInt(frm.doc.quantity.replace(/,/g, '')));
        }
    },
    quantity: function(frm) {
        if (frm.doc.quantity != null) {
            let formatted = Number(frm.doc.quantity).toLocaleString();
            frm.fields_dict.quantity.$wrapper.find('input').val(formatted);
        }
    },
    importing_company: function (frm) {
        if (frm.doc.importing_company) {
            frappe.db.get_doc('Precursor Company', frm.doc.importing_company).then(company_doc => {
                frm.set_value('importing_company_address', company_doc.company_address);
            });
        } else {
            frm.set_value('importing_company_address', '');
        }
    },
    precursor_chemical: function(frm) {
        frm.set_value('permit_no', '');
        if (frm.doc.precursor_chemical) {
            frappe.db.get_value('Substance', frm.doc.precursor_chemical, 'substance_code')
