        // Make an AJAX call to update the status of the linked book to "Issued"
        frappe.call({
            method: "nacoc.my_scripts.custom.update_book_status_on_issue",
            args: {
                book: book
            },
            callback: function(response) {
                console.log(response);
                // Handle the response
                if (response.message) {
                    frappe.msgprint("Book issued successfully");
                } else {
