                }
            }
        });
    }
});

function addWorkingDays(startDate, numWorkingDays) {
    var currentDate = new Date(startDate);
    var workingDaysAdded = 0;

    while (workingDaysAdded < numWorkingDays) {
        // Move to the next day
        currentDate.setDate(currentDate.getDate() + 1);

        // Check if the current day is a weekday (Monday to Friday)
        if (currentDate.getDay() !== 0 && currentDate.getDay() !== 6) {
            // Increment the count of working days added
            workingDaysAdded++;
        }
    }

    // Return the calculated due date
    return currentDate;
}

function formatDate(date) {
    var year = date.getFullYear();
    var month = String(date.getMonth() + 1).padStart(2, '0');
    var day = String(date.getDate()).padStart(2, '0');

    return `${year}-${month}-${day}`;
}

frappe.ui.form.on('Return Book', {
	onload: function(frm) {
        // Filter the Book field to only show books that have been issued
        frm.set_query('book', function() {
            return {
                filters: {
                    'status': 'Issued'
                }
            };
        });
    },
    return_date: function(frm) {
        // Get the return date and issue date values
        var returnDate = frm.doc.return_date;
        var issueDate = frm.doc.issue_date;

        // Perform validation only if both return date and issue date are set
        if (returnDate && issueDate) {
            // Check if return date is less than or equal to issue date
            if (returnDate <= issueDate) {
                frappe.msgprint({
                    title: __('Error'),
                    indicator: 'red',
                    message: __("Return Date must be later than the Issue Date")
                });
                // Clear the return date field
                frm.set_value('return_date', '');
            }
        }
    },
    book: function(frm) {
        // Retrieve the latest issuance of the selected book
        var book = frm.doc.book;
        frappe.call({
            method: 'nacoc.my_scripts.custom.get_latest_issuance',
            args: {
                book: book
            },
            callback: function(response) {
                if (response.message) {
                    // Automatically select the latest issuance
                    let issuance = response.message;
                    frm.set_value('employee', issuance.employee);
                    frm.set_value('issue_date', issuance.issue_date);
                    frm.set_value('due_date', issuance.due_date);
                    frm.refresh_fields();
                }
            }
        });
    },
    before_save: async function(frm) {
        // Get the book linked to the issue log
        var book = frm.doc.book;
        var condition = frm.doc.condition;

        // Validate that book and condition are not empty
        if (!book || !condition) {
            frappe.msgprint("Book or condition is empty");
            frappe.validated = false;
            return;
        }

        // Update the status of the linked book to the condition, and wait
        // for it to finish before letting the save proceed - frappe awaits
        // a before_save handler's returned promise, so this actually blocks
        // the save instead of racing it.
        try {
            const response = await frappe.call({
                method: "nacoc.my_scripts.custom.update_book_status",
                args: {
                    book: book,
                    condition: condition
                }
            });

            if (!response.message) {
                frappe.msgprint("An error occurred while updating book status");
                frappe.validated = false;
            }
        } catch (e) {
            frappe.msgprint("An error occurred while updating book status");
            frappe.validated = false;
        }
    }
});

