frappe.ui.form.on('Vehicle Maintenance Allowance', {
	refresh(frm) {
        // Register a single cleanup listener per form instance instead of
        // one per upload, so it doesn't leak a new closure on every file.
        if (!frm.__no_autosave_unload_bound__) {
            frm.__no_autosave_unload_bound__ = true;
            frm._pending_orphan_attachments = [];

            window.addEventListener('beforeunload', () => {
                if (!frm.is_dirty()) return;
                frm._pending_orphan_attachments.forEach(name => {
                    frappe.call('frappe.client.delete', {
                        doctype: 'File',
                        name: name
                    });
                });
            });
        }

        // Find all attach controls on the form
        frm.fields_dict && Object.values(frm.fields_dict).forEach(df => {
            if (df.df.fieldtype === 'Attach' || df.df.fieldtype === 'Attach Image') {
                // Override only once per control
                if (!df.__no_autosave_override__) {
                    df.__no_autosave_override__ = true;

                    const original = df.on_upload_complete;
                    df.on_upload_complete = function (attachment) {
                        // Call original logic except the auto-save part
                        if (attachment && attachment.file_url) {
                            this.set_value(attachment.file_url);
                            this.frm.dirty();
                            frappe.show_alert({ message: __('File attached successfully.'), indicator: 'green' });

                            // Track for cleanup if the user closes without saving
                            frm._pending_orphan_attachments.push(attachment.name);
                        }
                    };
                }
            }
        });
    }
});
